"""Exercise the real make argv generated by the TLS build patch."""
import json
import os
from pathlib import Path
import shlex
import shutil
import subprocess
import sys
import tempfile
import unittest

HERE = Path(__file__).resolve().parent

class KernelBuildTests(unittest.TestCase):
    def patched_make_calls(self, suffix):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            scripts = root / 'buildscripts'
            for name in ['scripts', 'include', 'deps/mbedtls/scripts', 'fake-bin']:
                (scripts / name).mkdir(parents=True)
            target = scripts / 'scripts/mbedtls.sh'
            shutil.copyfile(HERE / 'fixtures/mbedtls.sh', target)
            target.chmod(0o755)
            (scripts / 'include/depinfo.sh').write_text('cores=1\n')
            (scripts / 'include/path.sh').write_text(
                'ndk_suffix="$KAZUMI_TEST_SUFFIX"\nprefix_dir=/unused\n')
            config = scripts / 'deps/mbedtls/scripts/config.py'
            config.write_text('#!/usr/bin/env python3\n')
            config.chmod(0o755)
            make = scripts / 'fake-bin/make'
            make.write_text('#!/usr/bin/env python3\nimport json,os,sys\n'
                            'with open(os.environ["KAZUMI_MAKE_LOG"],"a") as f:\n'
                            ' f.write(json.dumps(sys.argv[1:])+"\\n")\n')
            make.chmod(0o755)
            subprocess.run(['git', 'apply', str(HERE / 'mbedtls-o2.patch')], cwd=root, check=True)
            log = root / 'make.jsonl'
            env = dict(os.environ, PATH=str(make.parent) + os.pathsep + os.environ['PATH'],
                       KAZUMI_TEST_SUFFIX=suffix, KAZUMI_MAKE_LOG=str(log))
            subprocess.run([str(target), 'build'], cwd=scripts / 'deps/mbedtls', env=env, check=True)
            return [json.loads(line) for line in log.read_text().splitlines()]

    def check_flags(self, suffix):
        calls = self.patched_make_calls(suffix)
        self.assertEqual(calls[0], ['clean'])
        self.assertEqual(len(calls), 3)
        for call in calls[1:]:
            # In particular, -fPIC must never become a make -f argument.
            self.assertFalse(any(argument.startswith('-f') for argument in call))
            for key in ['CFLAGS=', 'CXXFLAGS=']:
                flag = next(argument[len(key):] for argument in call if argument.startswith(key))
                self.assertIn('-O2', shlex.split(flag))
                self.assertIn('-fPIC', shlex.split(flag))
        return calls

    def test_arm32_build_and_install_preserve_optimization_and_quoting(self):
        self.check_flags('')

    def test_arm64_build_keeps_crypto_architecture_option(self):
        calls = self.check_flags('-arm64')
        self.assertIn('CFLAGS=-O2 -fPIC -march=armv8-a+crypto', calls[1])

    def test_excess_native_workers_fail_before_creating_workspace(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            spec = json.loads((HERE / 'kernel.json').read_text())
            (root / 'sdk/ndk' / spec['ndk']).mkdir(parents=True)
            work = root / 'work'
            result = subprocess.run([sys.executable, str(HERE / 'build_kernel.py'),
                                     '--work-dir', str(work), '--sdk', str(root / 'sdk'),
                                     '--jobs', '3'], capture_output=True, text=True)
            self.assertEqual(result.returncode, 2)
            self.assertIn('1 or 2', result.stderr)
            self.assertFalse(work.exists())

if __name__ == '__main__':
    unittest.main()
